package com.oms.order.service;

import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class RefundServiceTest {
    static JdbcTemplate db;OrderRepository repo;RefundService refunds;RefundWorkspace workspace;RefundSync sync;long platform,order;
    @BeforeAll static void start(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));db=OrderTestDatabase.jdbc(url);}
    @BeforeEach void reset(){for(String t:Arrays.asList("oms_refund_flow_task","oms_refund_flow_policy","oms_refund_api_item","oms_refund_api_cursor","oms_refund_goods_task","oms_refund_return_auto_task","oms_refund_bundle_claim","oms_refund_bundle_return","oms_refund_sync_item","oms_refund_sync","oms_refund_config","oms_refund_event","oms_refund_operation","oms_refund_return_plan","oms_refund","oms_platform_refund_snapshot","oms_platform_refund"))db.update("DELETE FROM "+t);for(String t:Arrays.asList("oms_order_update","oms_order_process_log","oms_order_shipment_line","oms_order_shipment","oms_order_line","oms_order","oms_platform_order_line","oms_platform_order","oms_order_pull_config"))db.update("DELETE FROM "+t);
        repo=new OrderRepository();ReflectionTestUtils.setField(repo,"jdbc",db);refunds=new RefundService();refunds.repository=repo;workspace=new RefundWorkspace();workspace.refunds=refunds;sync=new RefundSync();sync.refunds=refunds;sync.catalog=mock(OrderCatalog.class);when(sync.catalog.validateShop("VERIFY",1)).thenReturn(m());
        String payload=TmallOrderParserTest.payload("25");platform=repo.insert("INSERT INTO oms_platform_order(company_code,channel_id,platform_tid,platform_status,trade_type,seller_nick,source_modified,payload_hash,raw_payload,processing_payload,processing_hash,conversion_status) VALUES ('VERIFY',1,'987654321012345678','WAIT_SELLER_SEND_GOODS','fixed','seller','2026-10-01 00:00:00',?,?,?,?,'SUCCESS')",hash(payload),payload,payload,hash(payload));
        order=repo.insert("INSERT INTO oms_order(company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment,review_status) VALUES ('VERIFY','SO_REFUND',1,?,'987654321012345678','RESERVED',25,'APPROVED')",platform);db.update("UPDATE oms_platform_order SET business_order_id=? WHERE id=?",order,platform);db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES ('VERIFY',?,'987654321012345679','A','fixture',5,25,5)",order);
    }
    @AfterEach void clear(){for(String t:Arrays.asList("oms_refund_flow_task","oms_refund_flow_policy","oms_refund_api_item","oms_refund_api_cursor","oms_refund_goods_task","oms_refund_return_auto_task","oms_refund_bundle_claim","oms_refund_bundle_return","oms_refund_sync_item","oms_refund_sync","oms_refund_config","oms_refund_event","oms_refund_operation","oms_refund_return_plan","oms_refund","oms_platform_refund_snapshot","oms_platform_refund"))db.update("DELETE FROM "+t);sync.close();}
    Map<String,Object> source(int version,String fee,String status){Map<String,Object> p=m("refund_id","9007199254740993","tid","987654321012345678","oid","987654321012345679","seller_nick","seller","modified",String.format("2026-10-01 00:%02d:00",version),"refund_version",String.valueOf(version),"refund_fee",fee,"num",1,"status",status,"has_good_return",false,"reason","协商退款");return m("refund_id",p.get("refund_id"),"tid",p.get("tid"),"oid",p.get("oid"),"seller_nick","seller","status",status,"modified",p.get("modified"),"jdp_modified",p.get("modified"),"jdp_response",encode(m("refund_get_response",m("refund",p))));}
    long ingest(Map<String,Object> source){return number(refunds.tx().execute(s->refunds.ingest("VERIFY",1,"seller",source,"test")),"id");}
    long convert(long p){return number(refunds.convert("VERIFY",p,"test"),"id");}
    Map<String,Object> review(long id,String purpose,String goods){Map<String,Object> b=refunds.business("VERIFY",id,false),p=refunds.platform("VERIFY",number(b,"platform_refund_id"),false);return m("control_version",b.get("control_version"),"platform_version",p.get("version"),"purpose",purpose,"goods_action",goods,"reason","已协商确认","evidence","客服工单001");}
    @Test void durablePlatformConversionIsIdempotentAndRetainsOriginalOrder(){long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE"));assertNull(refunds.platform("VERIFY",p,false).get("business_refund_id"));long b=convert(p);assertEquals(b,convert(p));assertTrue(text(refunds.business("VERIFY",b,false),"refund_sn").startsWith("TK"));assertEquals(order,number(refunds.business("VERIFY",b,false),"order_id"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order",Integer.class));assertEquals(5,db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));assertFalse(OrderExchangeGuard.reason(repo,"VERIFY",order,false).isEmpty());}
    @Test void failedConversionDoesNotLoseSourceOrReleaseFulfillment(){db.update("DELETE FROM oms_order_line");long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE"));assertEquals("FAILED",refunds.convert("VERIFY",p,"test").get("state"));assertEquals("FAILED",refunds.platform("VERIFY",p,false).get("conversion_state"));assertFalse(text(repo.raw("VERIFY",platform),"refund_block_reason").isEmpty());assertThrows(IllegalArgumentException.class,()->OrderExchangeGuard.requireReady(repo,"VERIFY",order,true));}
    @Test void priceDifferenceKeepRequiresExplicitReviewAndDoesNotTouchStock(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));workspace.review("VERIFY",b,review(b,"DIFFERENCE","KEEP"),"test");assertEquals("",OrderExchangeGuard.reason(repo,"VERIFY",order,false));assertEquals("NONE",refunds.business("VERIFY",b,false).get("funds_state"));assertEquals(5,db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_refund_operation",Integer.class));}
    @Test void refusalRemainsBlockedEvenWhenPlatformAlreadyRefunded(){shipped();long b=convert(ingest(source(1,"25.00","SUCCESS")));workspace.review("VERIFY",b,review(b,"CANCEL","REFUSAL"),"test");Map<String,Object> row=refunds.business("VERIFY",b,false);assertEquals("SUCCESS",row.get("funds_state"));assertEquals("WAIT_ACTION",row.get("goods_state"));assertEquals("PROCESSING",row.get("state"));assertFalse(OrderExchangeGuard.reason(repo,"VERIFY",order,false).isEmpty());assertEquals(0,db.queryForObject("SELECT cancelled_quantity FROM oms_order_line",Integer.class));}
    @Test void platformStatusOnlyAdvancesFundsWithoutInvalidatingAdoptedPlan(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));workspace.review("VERIFY",b,review(b,"DIFFERENCE","KEEP"),"test");String snapshot=text(refunds.business("VERIFY",b,false),"approved_snapshot");ingest(source(2,"2.00","SUCCESS"));Map<String,Object> row=refunds.business("VERIFY",b,false);assertEquals("APPROVED",row.get("review_state"));assertEquals("COMPLETED",row.get("state"));assertEquals(snapshot,text(row,"approved_snapshot"));assertEquals(2,number(row,"approved_version"));assertEquals("",OrderExchangeGuard.reason(repo,"VERIFY",order,false));}
    @Test void changedAmountReblocksAndPreservesAdoptedSnapshot(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));workspace.review("VERIFY",b,review(b,"DIFFERENCE","KEEP"),"test");String snapshot=text(refunds.business("VERIFY",b,false),"approved_snapshot");ingest(source(2,"3.00","WAIT_SELLER_AGREE"));Map<String,Object> row=refunds.business("VERIFY",b,false);assertEquals("STALE",row.get("review_state"));assertEquals(snapshot,text(row,"approved_snapshot"));assertEquals("2.00",text(row,"refund_fee"));assertFalse(OrderExchangeGuard.reason(repo,"VERIFY",order,false).isEmpty());}
    @Test void olderVersionCannotOverwriteAndJsonKeyOrderIsNotAConflict(){Map<String,Object> fresh=source(2,"3.00","WAIT_SELLER_AGREE");long p=ingest(fresh);Map<String,Object> reordered=RefundValues.obj(fresh);Map<String,Object> parsed=RefundValues.parse(text(fresh,"jdp_response"));Map<String,Object> reverse=new TreeMap<>(Comparator.reverseOrder());reverse.putAll(parsed);reordered.put("jdp_response",encode(m("refund_get_response",m("refund",reverse))));ingest(reordered);assertEquals("VALID",refunds.platform("VERIFY",p,false).get("source_state"));ingest(source(1,"2.00","WAIT_SELLER_AGREE"));assertEquals("3.00",text(refunds.platform("VERIFY",p,false),"refund_fee"));assertEquals(1,number(refunds.platform("VERIFY",p,false),"version"));}
    @Test void sameVersionDifferentAmountIsBlockedAndSnapshotRetained(){long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE"));ingest(source(1,"3.00","WAIT_SELLER_AGREE"));assertEquals("CONFLICT",refunds.platform("VERIFY",p,false).get("source_state"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM oms_platform_refund_snapshot",Integer.class));assertEquals("FAILED",refunds.convert("VERIFY",p,"test").get("state"));}
    @Test void newerTrustedSuccessRestoresUnchangedPlanAfterSameVersionConflict(){long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE")),b=convert(p);workspace.review("VERIFY",b,review(b,"DIFFERENCE","KEEP"),"test");String original=text(refunds.business("VERIFY",b,false),"approved_snapshot");ingest(source(1,"2.00","SUCCESS"));assertEquals("STALE",refunds.business("VERIFY",b,false).get("review_state"));ingest(source(2,"2.00","SUCCESS"));Map<String,Object> live=refunds.business("VERIFY",b,false);assertEquals("VALID",refunds.platform("VERIFY",p,false).get("source_state"));assertEquals("APPROVED",live.get("review_state"));assertEquals("COMPLETED",live.get("state"));assertEquals(original,text(live,"approved_snapshot"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_refund_operation",Integer.class));}
    @Test void invalidRawDocumentIsRetainedBeforeConversion(){Map<String,Object> source=source(1,"2.00","WAIT_SELLER_AGREE");source.put("jdp_response","not json");long p=ingest(source);assertEquals("INVALID",refunds.platform("VERIFY",p,false).get("source_state"));assertEquals("not json",text(refunds.platform("VERIFY",p,false),"payload"));assertEquals("FAILED",refunds.convert("VERIFY",p,"test").get("state"));}
    @Test void sellerAndTenantIsolationCannotBeBypassed(){Map<String,Object> source=source(1,"2.00","WAIT_SELLER_AGREE");source.put("seller_nick","other");assertThrows(IllegalArgumentException.class,()->ingest(source));long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE"));long b=convert(p);assertThrows(IllegalArgumentException.class,()->refunds.platformDetail("OTHER",p));assertThrows(IllegalArgumentException.class,()->workspace.detail("OTHER",b));assertEquals(0,number(refunds.platformList("OTHER",Collections.emptyMap()),"total"));long snapshot=db.queryForObject("SELECT id FROM oms_platform_refund_snapshot",Long.class);assertThrows(IllegalArgumentException.class,()->refunds.snapshot("OTHER",p,snapshot));assertThrows(IllegalArgumentException.class,()->refunds.snapshot("VERIFY",p+1,snapshot));}
    @Test void optimisticReviewRejectsAnUpdatedPlatformVersion(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));Map<String,Object> old=review(b,"DIFFERENCE","KEEP");ingest(source(2,"3.00","WAIT_SELLER_AGREE"));assertThrows(IllegalArgumentException.class,()->workspace.review("VERIFY",b,old,"test"));assertEquals("PENDING",refunds.business("VERIFY",b,false).get("review_state"));}
    @Test void returnRefundIsPreservedButNotMistakenForOnlyRefund(){Map<String,Object> row=source(1,"2.00","WAIT_BUYER_RETURN_GOODS"),p=parse(text(row,"jdp_response"));p.put("has_good_return",true);p.put("dispute_type","REFUND_AND_RETURN");row.put("jdp_response",encode(m("refund",p)));long id=ingest(row);assertEquals("SUCCESS",refunds.convert("VERIFY",id,"test").get("state"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_refund",Integer.class));}
    @Test void missingPaymentVersionDoesNotDiscardJdpFacts(){Map<String,Object> row=source(1,"2.00","WAIT_SELLER_AGREE"),p=parse(text(row,"jdp_response"));p.remove("refund_version");row.put("jdp_response",encode(m("refund",p)));long id=ingest(row);assertEquals("VALID",refunds.platform("VERIFY",id,false).get("source_state"));assertTrue(convert(id)>0);}
    @Test void manualIdsTaskHasPerIdNotFoundAndDoesNotAdvanceAutomaticCursor(){config();Map<String,Object> command=m("channel_id",1,"mode","IDS","refund_ids","9007199254740993,9007199254740994","request_key","manual_request_001");long id=number(sync.submit("VERIFY",command,"test"),"id");assertEquals(id,number(sync.submit("VERIFY",command,"test"),"id"));db.update("UPDATE oms_refund_config SET lease_token='lease',lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND)");Map<String,Object> t=db.query("SELECT * FROM oms_refund_sync WHERE id=?",ROW,id).get(0);t.put("selected_ids",strings(t.get("selected_ids")));sync.commit("VERIFY",1,"lease",t,Collections.singletonList(source(1,"2.00","WAIT_SELLER_AGREE")));assertEquals("2026-10-01 00:00:00",text(sync.config("VERIFY",1,false),"cursor_time"));assertEquals("NOT_FOUND",db.queryForObject("SELECT result FROM oms_refund_sync_item WHERE refund_id='9007199254740994'",String.class));command.put("refund_ids","9007199254740995");assertThrows(IllegalArgumentException.class,()->sync.submit("VERIFY",command,"test"));}
    @Test void expiredLeaseRollsBackFactsAndCursorTogether(){config();long id=number(sync.submit("VERIFY",m("channel_id",1,"mode","MANUAL","start_time","2026-10-01 00:00:00","end_time","2026-10-02 00:00:00","request_key","manual_request_002"),"test"),"id");Map<String,Object> t=db.query("SELECT * FROM oms_refund_sync WHERE id=?",ROW,id).get(0);assertThrows(IllegalArgumentException.class,()->sync.commit("VERIFY",1,"expired",t,Collections.singletonList(source(1,"2.00","SUCCESS"))));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_platform_refund",Integer.class));assertEquals("PENDING",sync.task("VERIFY",id).get("state"));}
    @Test void refundArrivingBeforeOrderIsMaterializedWhenOriginalOrderIsPulled(){db.update("DELETE FROM oms_order_line");db.update("DELETE FROM oms_order");db.update("DELETE FROM oms_platform_order");ingest(source(1,"2.00","WAIT_SELLER_AGREE"));db.update("INSERT INTO oms_order_pull_config(company_code,channel_id,channel_name,source_key,seller_nick,initial_time,cursor_time) VALUES ('VERIFY',1,'fixture','fixture','seller',NOW(),NOW())");Map<String,Object> trade=m("tid","987654321012345678","seller_nick","seller","status","WAIT_SELLER_SEND_GOODS","type","fixed","jdp_modified","2026-10-01 00:00:00","jdp_response",TmallOrderParserTest.payload("25"));long p=number(refunds.tx().execute(s->repo.ingest("VERIFY",1,trade)),"platform_order_id");assertFalse(text(repo.raw("VERIFY",p),"refund_block_reason").isEmpty());}
    @Test void businessDetailsExposeActualIdentityButNotRawSourceByDefault(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));Map<String,Object> detail=workspace.detail("VERIFY",b);assertEquals(1,((List<?>)detail.get("lines")).size());assertFalse(obj(detail.get("platform")).containsKey("payload"));assertTrue(detail.get("shipments") instanceof List);}
    @Test void refundIdentityCannotBeMovedToAnotherOrderByANewerPayload(){long p=ingest(source(1,"2.00","WAIT_SELLER_AGREE"));Map<String,Object> row=source(2,"2.00","WAIT_SELLER_AGREE"),parsed=parse(text(row,"jdp_response"));parsed.put("tid","987654321012345680");row.put("tid",parsed.get("tid"));row.put("jdp_response",encode(m("refund",parsed)));ingest(row);assertEquals("CONFLICT",refunds.platform("VERIFY",p,false).get("source_state"));assertEquals("987654321012345678",refunds.platform("VERIFY",p,false).get("platform_tid"));assertFalse(text(repo.raw("VERIFY",platform),"refund_block_reason").isEmpty());}
    @Test void refusalAndReturnNeedActualOutboundFacts(){long b=convert(ingest(source(1,"2.00","WAIT_SELLER_AGREE")));assertThrows(IllegalArgumentException.class,()->workspace.review("VERIFY",b,review(b,"CANCEL","REFUSAL"),"test"));}
    void shipped(){long id=repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,status,created_by) VALUES ('VERIFY','XS_REFUND',?,'SO_REFUND',1,'987654321012345678',1,'O','R','R',5,'SHIPPED','test')",order);long line=db.queryForObject("SELECT id FROM oms_order_line WHERE order_id=?",Long.class,order);db.update("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,?,'987654321012345679','A','fixture',5,5,1,1,'V',1,'PUBLIC_EXTRA')",id,line);}
    void config(){db.update("INSERT INTO oms_refund_config(company_code,channel_id,source_key,seller_nick,initial_time,cursor_time,updated_by) VALUES ('VERIFY',1,'fixture','seller','2026-10-01 00:00:00','2026-10-01 00:00:00','test')");}
    @Test void returnRefundRequiresReturnActionAndFiltersIndependently(){
        shipped();Map<String,Object> row=source(1,"8.00","WAIT_BUYER_RETURN_GOODS"),p=parse(text(row,"jdp_response"));p.put("has_good_return",true);p.put("dispute_type","REFUND_AND_RETURN");row.put("jdp_response",encode(m("refund",p)));long id=convert(ingest(row));
        assertThrows(IllegalArgumentException.class,()->workspace.review("VERIFY",id,review(id,"DIFFERENCE","KEEP"),"test"));workspace.review("VERIFY",id,review(id,"CANCEL","RETURN"),"test");assertEquals("WAIT_ACTION",refunds.business("VERIFY",id,false).get("goods_state"));assertEquals(1,number(refunds.businessList("VERIFY",Collections.singletonMap("disputeType","REFUND_AND_RETURN")),"total"));assertEquals(0,number(refunds.businessList("VERIFY",Collections.singletonMap("disputeType","REFUND")),"total"));
    }
    @Test void platformLogisticsChangeRetainsApprovalButTypeChangeNeedsReapprovalWithoutAnotherTk(){
        shipped();long id=convert(ingest(source(1,"8.00","WAIT_SELLER_AGREE")));workspace.review("VERIFY",id,review(id,"CANCEL","RETURN"),"test");Map<String,Object> row=source(2,"8.00","WAIT_SELLER_CONFIRM_GOODS"),p=parse(text(row,"jdp_response"));p.put("sid","SF123");p.put("company_name","SF");row.put("jdp_response",encode(m("refund",p)));ingest(row);assertEquals("APPROVED",refunds.business("VERIFY",id,false).get("review_state"));
        row=source(3,"8.00","WAIT_SELLER_CONFIRM_GOODS");p=parse(text(row,"jdp_response"));p.put("has_good_return",true);p.put("dispute_type","REFUND_AND_RETURN");row.put("jdp_response",encode(m("refund",p)));ingest(row);assertEquals("STALE",refunds.business("VERIFY",id,false).get("review_state"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_refund",Integer.class));workspace.review("VERIFY",id,review(id,"CANCEL","RETURN"),"test");assertEquals("APPROVED",refunds.business("VERIFY",id,false).get("review_state"));
    }
}
